import { navigate } from "gatsby";
import React, { useEffect, useState } from "react";
import type { Quote } from "../types";
import { listQuotes } from "../../../sessionServices/quotes/quotesService";
import { listUsers } from "../../../sessionServices/users/usersService";
import type { UserProfile } from "../types";

type QuoteWithId = Quote & { id: string };

const STATUS_BADGE: Record<string, string> = {
  draft: "bg-gray-100 text-gray-600",
  sent: "bg-blue-100 text-blue-700",
  approved: "bg-green-100 text-green-700",
  rejected: "bg-red-100 text-red-600",
  expired: "bg-yellow-100 text-yellow-700",
};

export function QuoteList() {
  const [quotes, setQuotes] = useState<QuoteWithId[]>([]);
  const [users, setUsers] = useState<Record<string, UserProfile>>({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function load() {
      const [quotesData, usersData] = await Promise.all([listQuotes(), listUsers()]);
      const userMap: Record<string, UserProfile> = {};
      for (const u of usersData) userMap[u.uid] = u;
      setQuotes(quotesData);
      setUsers(userMap);
      setLoading(false);
    }
    load();
  }, []);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <div className="h-6 w-6 animate-spin rounded-full border-4 border-gray-300 border-t-gray-800" />
      </div>
    );
  }

  if (quotes.length === 0) {
    return (
      <p className="text-sm text-gray-400">No quotes yet. Create the first one.</p>
    );
  }

  return (
    <div className="overflow-hidden rounded-xl bg-white shadow-sm ring-1 ring-gray-200">
      <table className="w-full text-sm">
        <thead>
          <tr className="border-b border-gray-100 bg-gray-50 text-left text-xs font-medium uppercase tracking-wide text-gray-500">
            <th className="px-4 py-3">Title</th>
            <th className="px-4 py-3">Client</th>
            <th className="px-4 py-3">Status</th>
            <th className="px-4 py-3">Valid until</th>
            <th className="px-4 py-3" />
          </tr>
        </thead>
        <tbody className="divide-y divide-gray-100">
          {quotes.map((q) => {
            const client = users[q.userId];
            return (
              <tr
                key={q.id}
                className="cursor-pointer transition hover:bg-gray-50"
                onClick={() => navigate(`/admin/quotes/${q.id}`)}
              >
                <td className="px-4 py-3 font-medium text-gray-900">{q.title}</td>
                <td className="px-4 py-3 text-gray-600">
                  {client ? client.fullName : <span className="text-gray-400 italic">Unknown</span>}
                </td>
                <td className="px-4 py-3">
                  <span className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium ${STATUS_BADGE[q.status] ?? "bg-gray-100 text-gray-600"}`}>
                    {q.status}
                  </span>
                </td>
                <td className="px-4 py-3 text-gray-500">
                  {q.validUntil
                    ? (q.validUntil as { toDate: () => Date }).toDate().toLocaleDateString("en-CA")
                    : "—"}
                </td>
                <td className="px-4 py-3 text-right">
                  <span className="text-xs text-gray-400 underline">View</span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
